def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Inputs must be strings")

    if len(a) != len(b):
        raise ValueError("Input strings must have the same length")

    if not a:
        return ""

    try:
        # Base 2 conversion is efficient and exempt from string-to-int limits.
        # Bitwise XOR is performed at the C level.
        result = int(a, 2) ^ int(b, 2)
        # zfill ensures the result matches the input length by preserving leading zeros.
        return bin(result)[2:].zfill(len(a))
    except ValueError:
        raise ValueError("Strings must contain only '0' and '1'")

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if not isinstance(n, int):
        raise TypeError("Input n must be an integer")
    if n < 0:
        return ""

    # join() and map() are efficient, but large n can lead to memory exhaustion.
    return ' '.join(map(str, range(n + 1)))

